#!/usr/bin/env python3
"""Generate the single-download shell installer from reviewed Python helpers."""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent
FILES = ('runtime_dependencies.py', 'verify-install.py', 'bootstrap-install.py')
HEADER = '''#!/bin/sh
# Generated by scripts/build-bootstrap.py. Initial trust: reviewed GitHub HTTPS source.
# Signed release downloads are authenticated before their code can execute.
set -eu
if [ "$(id -u)" -eq 0 ]; then
    echo 'Run as your regular desktop user, not with sudo.' >&2; exit 1
fi
if ! command -v python3 >/dev/null 2>&1; then
    echo 'Python 3.11+ is needed to verify downloads.' >&2
    case "$(. /etc/os-release; echo "${ID:-}")" in
        fedora) echo 'Install it with sudo dnf install python3, then retry.' >&2;;
        debian|ubuntu|pop) echo 'Install it with sudo apt-get install python3, then retry.' >&2;;
    esac
    exit 1
fi
umask 077
temporary=$(mktemp -d "${TMPDIR:-/tmp}/decksmith-bootstrap.XXXXXXXX")
trap 'rm -rf -- "$temporary"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP
'''


def render():
    content = HEADER
    for number, name in enumerate(FILES):
        marker = 'DECKSMITH_SOURCE_' + str(number)
        source = (ROOT / name).read_text()
        if marker in source.splitlines():
            raise ValueError('Heredoc marker occurs in source')
        content += 'cat > "$temporary/' + name + '" <<\'' + marker + "'\n" + source + '\n' + marker + '\n'
    return content + 'python3 -I -B "$temporary/bootstrap-install.py" "$@"\n'


if __name__ == '__main__':
    expected = render()
    destination = ROOT / 'install.sh'
    if '--check' in sys.argv:
        if destination.read_text() != expected:
            raise SystemExit('Installer is stale. Run python3 scripts/build-bootstrap.py.')
    else:
        destination.write_text(expected)
